<script setup lang="ts">
import{computed,onMounted,ref}from"vue";import ConfirmDialog from"./ConfirmDialog.vue";import"../crawler-scheduler.css";
type State="loading"|"ready"|"warning"|"blocked"|"empty"|"forbidden"|"expired"|"rate_limited"|"unavailable"|"recovering";
interface Dto{state:"ready"|"warning"|"blocked";topology:{mode:"single_host";worker_instances:number;crawler_instances:number;maximum_workers:1;maximum_crawlers:1};leases:{active_worker:number;active_crawler:number;duplicate_count:number};providers:Array<{id:string;code:string;configured_concurrency:number;effective_concurrency:number;active_leases:number}>;profiles:Array<{id:string;active_leases:number}>;resource:{load_basis_points:number;available_memory_mb:number;free_disk_mb:number;observed_at:string};findings:Array<{code:string;severity:"warning"|"blocked";action_hint:string}>;observed_at:string;capacity_claim:"unverified"}
const props=defineProps<{apiBaseUrl:string}>(),state=ref<State>(new URLSearchParams(location.search).get("state")==="recovering"?"recovering":"loading"),data=ref<Dto|null>(null),requestId=ref(""),message=ref(""),confirming=ref(false),saving=ref(false);const verdict=computed(()=>({loading:["正在核验单机调度","读取进程、租约、来源并发和资源水位。"],recovering:["正在回收过期租约","只处理服务端确认已过期的调度槽位。"],ready:["Crawler 单机调度门已满足","一个 Worker、一个 Crawler、来源并发 1 且资源水位正常。"],warning:["单机资源接近停止线","继续保持并发 1，并观察资源水位。"],blocked:["Crawler 单机调度已阻断","保持任务排队，按告警动作通过宝塔恢复。"],empty:["尚无调度观测","确认宝塔 Node API、Node Worker 与 Python Crawler 已运行。"],forbidden:["没有平台运维权限","联系平台管理员授予 platform:operate。"],expired:["登录已失效","重新登录后核验调度状态。"],rate_limited:["刷新过于频繁","稍后再试，当前租约不受影响。"],unavailable:["单机调度事实暂不可用","检查 MySQL、本机 /proc 和受控目录后重试。"]} as const)[state.value]);const pct=(value:number)=>`${(value/100).toFixed(1)}%`,time=(value:string)=>new Intl.DateTimeFormat("zh-CN",{month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit"}).format(new Date(value));const status=(code:number):State=>code===401?"expired":code===403?"forbidden":code===429?"rate_limited":"unavailable";
async function load(){state.value="loading";message.value="";try{const response=await fetch(`${props.apiBaseUrl}/platform/operations/crawler-scheduler`,{credentials:"include",headers:{accept:"application/json"}}),body=await response.json().catch(()=>null);requestId.value=body?.request_id??"";if(!response.ok){state.value=status(response.status);message.value=body?.error?.action_hint??"";return;}data.value=body.data??null;state.value=data.value?data.value.state:"empty";}catch{state.value="unavailable";}}
async function recover(){saving.value=true;state.value="recovering";try{const response=await fetch(`${props.apiBaseUrl}/platform/operations/crawler-scheduler/recover-expired`,{method:"POST",credentials:"include",headers:{"content-type":"application/json","idempotency-key":crypto.randomUUID()},body:"{}"}),body=await response.json().catch(()=>null);requestId.value=body?.request_id??"";message.value=response.ok?`已回收 ${body.data.recovered} 个过期调度槽位`:body?.error?.action_hint??"回收未完成";if(response.ok)await load();else state.value=status(response.status);}catch{state.value="unavailable";}finally{saving.value=false;confirming.value=false;}}
onMounted(()=>{if(state.value!=="recovering")void load();});
</script>
<template><section class="crawler-scheduler" :data-state="state"><header class="crawler-scheduler__hero"><div><p>SINGLE HOST SCHEDULER · M08-05</p><h2>Crawler 单机调度</h2><span>惠州单机固定一个 Node Worker、一个 Python Crawler；来源并发上限 1，不启用负载均衡或备用服务器。</span></div><div><button type="button" @click="load">刷新运行事实</button><button class="danger" type="button" :disabled="saving" @click="confirming=true">回收过期租约</button></div></header><section v-if="!['ready','warning','blocked'].includes(state)" class="crawler-scheduler__state" :data-kind="state" aria-live="polite"><i></i><div><b>{{verdict[0]}}</b><p>{{message||verdict[1]}}</p><code v-if="requestId">request_id {{requestId}}</code></div><button v-if="!['loading','recovering'].includes(state)" type="button" @click="load">重新核验</button></section><template v-else-if="data"><section class="crawler-scheduler__verdict" :data-verdict="state"><div><small>S0 · {{state.toUpperCase()}}</small><strong>{{verdict[0]}}</strong></div><p>{{verdict[1]}}</p><em>单机 · 容量未验证</em></section><section class="crawler-scheduler__metrics"><article><span>Node Worker</span><strong>{{data.topology.worker_instances}} / {{data.topology.maximum_workers}}</strong><small>全局任务槽位 {{data.leases.active_worker}}</small></article><article><span>Python Crawler</span><strong>{{data.topology.crawler_instances}} / {{data.topology.maximum_crawlers}}</strong><small>活动浏览器槽位 {{data.leases.active_crawler}}</small></article><article><span>1 分钟归一化负载</span><strong>{{pct(data.resource.load_basis_points)}}</strong><small>按当前 CPU 核数归一化</small></article><article><span>可用内存 / 磁盘</span><strong>{{data.resource.available_memory_mb}} MB</strong><small>{{data.resource.free_disk_mb}} MB 可用磁盘</small></article></section><div class="crawler-scheduler__layout"><section class="crawler-scheduler__panel"><header><div><p>SOURCE QUOTAS</p><h3>来源并发门</h3></div><span>配置值会被 S0 上限收紧到 1</span></header><div class="crawler-scheduler__sources"><article v-for="item in data.providers" :key="item.id"><div><b>{{item.code}}</b><span>{{item.active_leases}} / {{item.effective_concurrency}}</span></div><progress :value="item.active_leases" :max="item.effective_concurrency||1"></progress><small>来源配置 {{item.configured_concurrency}} · 当前有效 {{item.effective_concurrency}}</small></article><p v-if="!data.providers.length">当前没有启用来源。</p></div></section><aside class="crawler-scheduler__panel"><header><div><p>EXCLUSIVE PROFILES</p><h3>浏览器档案独占</h3></div><span>{{data.profiles.length}} 个活动档案</span></header><dl><div><dt>重复租约</dt><dd>{{data.leases.duplicate_count}}</dd></div><div><dt>独占上限</dt><dd>每档案 1</dd></div><div><dt>全局 Crawler</dt><dd>1</dd></div><div><dt>租约真相</dt><dd>MySQL 5.7</dd></div></dl></aside></div><section class="crawler-scheduler__panel crawler-scheduler__findings"><header><div><p>FAIL-CLOSED GATES</p><h3>调度与资源告警</h3></div><span>{{data.findings.length}} 项</span></header><div v-if="data.findings.length"><article v-for="(item,index) in data.findings" :key="item.code" :data-severity="item.severity"><span>{{String(index+1).padStart(2,'0')}}</span><code>{{item.code}}</code><p>{{item.action_hint}}</p></article></div><div v-else class="crawler-scheduler__clear"><b>当前无单机调度阻断</b><span>这不代表多节点、负载均衡、备用服务器或容量已经验证。</span></div></section><footer><span>资源观测 {{time(data.resource.observed_at)}}</span><span>request_id {{requestId||'—'}}</span><strong>服务、重启与有限任务只允许通过宝塔</strong></footer></template><ConfirmDialog :open="confirming" title="回收过期调度租约？" description="仅删除服务端确认已经过期的 Worker、Crawler 与来源调度槽位。" impact="不会终止有效任务，不会删除采集历史、审计或浏览器档案。" confirm-label="确认回收" confirmation-text="确认回收" @cancel="confirming=false" @confirm="recover"/></section></template>
